local M = { entries = {} }

function M.add(name, score)
    M.entries[#M.entries + 1] = { name = name, score = score }
end

function M.best()
    local top = nil
    for _, e in ipairs(M.entries) do
        if top == nil or e.score > top.score then top = e end
    end
    return top
end

return M

local defaults = { speed = 4, hp = 100 }
local player = { name = "Emre" }

setmetatable(player, {
    __index = defaults     -- missing keys are looked up here
})

print(player.name)     -- Emre   (its own field)
print(player.speed)    -- 4      (from defaults)
print(player.hp)       -- 100

-- __index as a function: nothing is stored on disk, everything is computed
local doubling = setmetatable({}, {
    __index = function(_, key)
        return (tonumber(key) or 0) * 2
    end
})
print(doubling[21])    -- 42

#native <Embed>
#native <Stdio>

int main() {
    /* seed two slots the Lua side will read */
    Embed.SendValue(type="lua", name="target_x", 400.0);
    Embed.SendValue(type="lua", name="speed", 3.0);

    Embed.Run(type="lua");          /* runs scripts/main.lua */
    Embed.Stop(type="lua");         /* waits for the window to close */

    /* read back what Lua wrote */
    int score = Embed.GetValue(type="lua", name="score");
    Stdio.printf("score = {}\n", score);
    return 0;
}

